public class Main {
    static int n, m;
    static int[][] grid;
    static boolean[][] visited;
    static int[] dy = {0, 0, 1, -1};
    static int[] dx = {1, -1, 0, 0};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        grid = new int[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) - '0';
            }
        }

        int water = 0;

        for (int level = 1; level < 10; level++) {
            Queue<int[]> queue = new LinkedList<>();
            boolean[][] tempVisited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (i == 0 || i == n-1 || j == 0 || j == m-1) {
                        if (grid[i][j] <= level && !visited[i][j]) {
                            queue.offer(new int[]{i, j});
                            tempVisited[i][j] = true;
                        }
                    }
                }
            }

            while (!queue.isEmpty()) {
                int[] pos = queue.poll();
                int y = pos[0], x = pos[1];
                for (int d = 0; d < 4; d++) {
                    int ny = y + dy[d];
                    int nx = x + dx[d];
                    if (ny >= 0 && ny < n && nx >= 0 && nx < m) {
                        if (!tempVisited[ny][nx] && grid[ny][nx] <= level && !visited[ny][nx]) {
                            tempVisited[ny][nx] = true;
                            queue.offer(new int[]{ny, nx});
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!tempVisited[i][j] && !visited[i][j] && grid[i][j] < level) {
                        water += level - grid[i][j];
                        visited[i][j] = true;
                    }
                }
            }
        }

        System.out.println(water);
    }
}

