import java.util.*;

public class Main {
    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static int lcm(int a, int b) {
        return a / gcd(a, b) * b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextInt();
        }

        boolean[] visited = new boolean[n];
        List<Integer> cycles = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int count = 0;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    count++;
                    curr = p[curr];
                }
                cycles.add(count);
            }
        }

        int resultLcm = cycles.get(0);
        for (int i = 1; i < cycles.size(); i++) {
            resultLcm = lcm(resultLcm, cycles.get(i));
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (p[i] != (i + resultLcm) % n) {
                count++;
            }
        }

        System.out.println(count);
        sc.close();
    }
}

