bool unite(int x, int y) {
    int px = find(x);
    int py = find(y);
    if (px == py) return false;

    if (rankArr[px] < rankArr[py]) {
        swap(px, py);
    }
    parent[py] = px;
    if (rankArr[px] == rankArr[py]) {
        rankArr[px]++;
    }
    return true;
}

